-- Only for the empty, explicitly approved Conta Facil test project. All fixtures and extension creation roll back.
begin;
do $$ begin if exists(select 1 from auth.users) or exists(select 1 from public.tenants) then raise exception 'Hosted probe requires the empty dedicated test project'; end if; end $$;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated,anon;
set local search_path=public,extensions;
create temporary table conta_hosted_results(message text);
grant select,insert on conta_hosted_results to authenticated,anon;
select ('50000000-0000-0000-0000-00000000000'||case when d.name='A' then '1' else '2' end)::uuid,d.tenant_id,c.id,d.id,'CRC',jsonb_build_object('name',c.name),m.user_id,m.user_id,gen_random_uuid(),'hosted_probe' from public.departments d join public.customers c on c.tenant_id=d.tenant_id join public.memberships m on m.tenant_id=d.tenant_id;
set local role authenticated;
do $$ begin perform set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","aal":"aal2","session_id":"30000000-0000-0000-0000-000000000001"}',true); end $$;
with changed as(update public.departments set name='intrusion' where tenant_id='20000000-0000-0000-0000-000000000002' returning *) insert into conta_hosted_results select is((select count(*)::int from changed),0,'cross-tenant update denied');
do $$ begin perform set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","aal":"aal1","session_id":"30000000-0000-0000-0000-000000000001"}',true); end $$;
reset role;
update private.sessions set revoked_at=now() where id='test';
set local role authenticated;
reset role;
set local role anon;
reset role;
select jsonb_build_object('passed',bool_and(message not like 'not ok%' and message not like '# Looks like%'),'assertions',count(*) filter(where message ~ '^(ok|not ok) '),'messages',jsonb_agg(message)) verification from conta_hosted_results;
rollback;
